  [415004] = { nil, "Energia magica esaurita", nil, 0x842a0ccf, "mu" },
  [415005] = { nil, "Traboccante di energia magica", nil, 0xc432adfa, "mu" },
  [415012] = { nil, "Pieno d'ispirazione.", nil, 0x12978998, "mu" },
  [415015] = { nil, "Pieno d'ispirazione.", nil, 0x12978998, "mu" },
  [415058] = { nil, "Ottieni il $N1% del mana totale ogni $D1. Si annulla lanciando incantesimi di cura.", nil, 0x70961940, "mu" },
  [415059] = { "Ottieni il $N1% del tuo mana massimo ogni $D1 per $D2 dopo aver bloccato un attacco in mischia. Questo effetto viene annullato lanciando ⟦Flash of Light=Lampo di Luce⟧, ⟦Holy Light=Luce Sacra⟧ o ⟦Holy Shock=Folgore Sacra⟧.", nil, 0xe3500efc, nil, "um" },
  [415068] = { "Infligge $N1 danni da sacro a un bersaglio nemico e ha una probabilità del $N2% di infliggere un colpo critico contro Demoni e Non Morti.", nil, 0x57ba1b36, nil, "um" },
  [415069] = { "Infligge $N1 danni da sacro a un bersaglio nemico e ha una probabilità del $N2% di infliggere un colpo critico contro Demoni e Non Morti.", nil, 0x57ba1b36, nil, "um" },
  [415070] = { "Infligge $N1 danni da sacro a un bersaglio nemico e ha una probabilità del $N2% di infliggere un colpo critico contro Demoni e Non Morti.", nil, 0x57ba1b36, nil, "um" },
  [415071] = { "Infligge $N1 danni da sacro a un bersaglio nemico e ha una probabilità del $N2% di infliggere un colpo critico contro Demoni e Non Morti.", nil, 0x57ba1b36, nil, "um" },
  [415072] = { "Infligge $N1 danni da sacro a un bersaglio nemico e ha una probabilità del $N2% di infliggere un colpo critico contro Demoni e Non Morti.", nil, 0x57ba1b36, nil, "um" },
  [415073] = { "Infligge $N1 danni da sacro a un bersaglio nemico e ha una probabilità del $N2% di infliggere un colpo critico contro Demoni e Non Morti.", nil, 0x57ba1b36, nil, "um" },
  [415076] = { "Esorcismo ora può essere lanciato su qualsiasi bersaglio e ha una probabilità di critico aumentata del $N1% contro Non Morti e Demoni.", nil, 0x46184a7e, nil, "um" },
  [415096] = { "L'efficacia della tua Catena di Guarigione si riduce solo del $N1% per ogni balzo, e quella di ⟦Chain Lightning=Catena di Fulmini⟧ solo del $N2% per ogni balzo. Ciascuna balza inoltre su $N3 bersaglio aggiuntivo.", nil, 0xec24d616, nil, "um" },
  [415100] = { "Ogni volta che ⟦Flame Shock=Folgore del Fuoco⟧ infligge danni, ha il $N1% di probabilità di azzerare il tempo di recupero di ⟦Lava Burst=Getto di Lava⟧ e ⟦Chain Lightning=Catena di Fulmini⟧ e di rendere istantaneo il tuo prossimo ⟦Lava Burst=Getto di Lava⟧ o ⟦Chain Lightning=Catena di Fulmini⟧ entro $D1. Ogni volta che Marea Gelida cura, ha il $N3% di probabilità di rendere istantanea la tua prossima ⟦Chain Heal=Catena di Guarigione⟧ entro $D2. Inoltre, ogni $D3 ottieni mana pari al $N6% del tuo Intelletto.", nil, 0xd71b275c, nil, "um" },
  [415105] = { nil, "Il tuo prossimo incantesimo ⟦Chain Lightning=Catena di Fulmini⟧ o ⟦Lava Burst=Getto di Lava⟧ sarà istantaneo.", nil, 0xc9bceb20, "mu" },
  [415140] = { "Aumenta la tua potenza d'attacco di un valore pari al $N1% del tuo Intelletto.", nil, 0xeada9b4a, nil, "um" },
  [415144] = { nil, "Potenza d'attacco aumentata di $N1.\nDanni magici aumentati di $N2.", nil, 0x56ab3fa3, "mu" },
  [415231] = { "La tua ⟦Flame Shock=Folgore del Fuoco⟧ ora colpisce fino a $N1 bersagli, la sua durata aumenta di $D1 e infligge il $N3% di danni in più. Inoltre, mentre l'arma equipaggiata nella mano primaria è infusa con Arma della Lingua di Fuoco, ottieni danni magici aumentati di un valore pari al $N4% del tuo Intelletto.", nil, 0x86fd71c5, nil, "um" },
  [415233] = { "Trasforma lo Sciamano in un ⟦Ghost Wolf=Lupo Spettrale⟧, aumentando la velocità del $N1% e riducendo tutti i danni subiti del $N2%.", "Aumenta la velocità di movimento del $N1%.\nRiduce i danni subiti del $N2%.", 0xf0182eac, 0x7954b22c, "uu" },
  [415236] = { "Seleziona l'area di $N1 m intorno al giocatore bersaglio e cura tutti i membri del suo gruppo presenti in quell'area di $N2 ogni secondo.", "Cura di $N1 ogni secondo il gruppo del giocatore bersaglio che si trova nella tua Pioggia Curativa.", 0x7f3d1dc2, 0x783d5a8e, "uu" },
  [415240] = { nil, "Nella Pioggia Curativa di uno Sciamano.", nil, 0x82e1098b, "mu" },
  [415242] = { "Cura di $N3 fino a $N1 membri amici del gruppo o dell'incursione entro $N2 m dal bersaglio.", nil, 0x76647811, nil, "um" },
  [415292] = { "Cura di $N1 in $D1.", "Cura di $N1 ogni $D1.", 0xf5fa5e54, 0x15b97dff, "uu" },
  [415320] = { "Tu e il tuo famiglio infliggete simultaneamente e istantaneamente il $N1% dei danni in mischia. In seguito, infliggi il $N2% di danni in più per $D1, effetto cumulabile fino a $N4 volte. Gli attacchi base del tuo famiglio hanno il $N5% di probabilità di azzerare il tempo di recupero di Assalto Fiancheggiato.", "Tutti i danni aumentati del $N1%.", 0x740af0fc, 0x7977b3df, "uu" },
  [415326] = { "Tu e il tuo famiglio infliggete simultaneamente e istantaneamente il $N1% dei danni in mischia. In seguito, il tuo Morso della Mangusta e il tuo Assalto del Raptor infliggono il $N2% di danni in più per $D1, effetto cumulabile fino a $N4 volte. Assalto del Raptor ha il $N5% di probabilità di azzerare il tempo di recupero di Assalto Fiancheggiato.", nil, 0x5836961c, nil, "um" },
  [415352] = { "Assalto del Raptor è ora istantaneo, e Morso della Mangusta e Assalto del Raptor hanno il $N1% di probabilità a ogni attacco di azzerare i tempi di recupero di Morso della Mangusta e Assalto del Raptor.", nil, 0x01109410, nil, "um" },
  [415358] = { "Assalto del Raptor aumenta del $N1% i danni inflitti da Assalto del Raptor e Morso della Mangusta per $D1, cumulabile fino a $N3 volte. Le applicazioni successive non prolungano la durata di questo effetto.", nil, 0xc6ec38f2, nil, "um" },
  [415362] = { nil, "Danni di Assalto del Raptor e Morso della Mangusta aumentati del $N1%.", nil, 0x5c4cbf9d, "mu" },
  [415370] = { "Infliggi il $N1% di danni in più con tutti gli attacchi mentre non hai un famiglio attivo.", nil, 0x00437013, nil, "um" },
  [415372] = { nil, "Danni ridotti del $N1% mentre hai un famiglio.", nil, 0x08033dd9, "mu" },
  [415399] = { "Quando non ti sei mosso nell'ultimo $D1, hai il $N2% di probabilità di ottenere Sniper's Aim, cumulabile fino a $N3 volte. Sniper's Aim aumenta del $N4% la probabilità di critico delle tue abilità di tiro.", nil, 0x666248c2, nil, "um" },
  [415401] = { nil, "Probabilità di critico delle abilità di tiro aumentata del $N1%.", nil, 0x33595f54, "mu" },
  [415405] = { "Riduce il tempo di recupero della tua abilità ⟦Rapid Fire=Rapidità di Tiro⟧ di $D1. Inoltre, quando uccidi un nemico non banale o questi muore mentre è afflitto dal tuo Morso del Serpente, ottieni Uccisione Rapida, che aumenta del $N3% i danni della tua prossima abilità di tiro entro $D2.", nil, 0x780100d7, nil, "um" },
  [415407] = { "Aumenta del $N1% i danni della tua prossima abilità di tiro.", "La prossima abilità di tiro infligge il $N1% di danni in più.", 0x234e79c9, 0x4114209a, "uu" },
  [415413] = { "Ogni volta che piazzi una trappola, la tua prossima abilità di tiro (tranne ⟦Scatter Shot=Tiro Disorientante⟧) entro $D1 non costa mana e non attiva il tempo di recupero.", nil, 0x623278dd, nil, "um" },
  [415414] = { nil, "La prossima abilità di tiro non costa mana e non attiva il tempo di recupero.", nil, 0x7cac3007, "mu" },
  [415423] = { "Il Cacciatore assume l'aspetto della vipera: i tuoi attacchi automatici a distanza e in mischia rigenerano mana, ma i danni totali che infliggi sono ridotti del $N1%. Inoltre, ottieni il $N2% del mana massimo ogni $D1. Il mana ottenuto dipende dalla velocità dell'arma. Può essere attivo un solo Aspetto alla volta.", "I tuoi attacchi automatici a distanza e in mischia rigenerano una percentuale del tuo mana base, ma i danni totali che infliggi sono ridotti del $N1%. Inoltre, ottieni il $N2% del mana massimo ogni $D1.", 0x5c074219, 0xcddcfcf7, "uu" },
  [415428] = { "Aumenta la tua probabilità di schivata del $N1% e quella del tuo famiglio del $N2%. Inoltre, riduce del $N3% il tempo di recupero della tua abilità Assalto Fiancheggiato.", nil, 0x62e616f4, nil, "um" },
  [415449] = { "Equipaggia un oggetto per lo spazio Vita con una runa incisa per attivare un'abilità in questo spazio.", nil, 0xa309a047, nil, "um" },
  [415450] = { "Equipaggia un oggetto per lo spazio Piedi con una runa incisa per attivare un'abilità in questo spazio.", nil, 0x94e65c6e, nil, "um" },
  [415452] = { "Ottieni l'abilità Improved Swipe:\n\n$I1\nIn Forma Felina, la tua abilità Spazzata diventa Swipe (Cat), e in Forma d'Orso la tua abilità Spazzata colpisce fino a $N1 nemici aggiuntivi.\n\nSwipe (Cat)\n$I2\nSpazza i nemici vicini, infliggendo il $N2% dei danni dell'arma e generando $N3 punti combo sul tuo bersaglio attuale.", nil, 0xe2527d73, nil, "um" },
  [415457] = { "Ottieni l'abilità Ventaglio di Lame:\n\n$I1\nScaglia istantaneamente entrambe le armi contro tutti i bersagli entro $N1 m, infliggendo il $N2% dei danni dell'arma con i pugnali e il $N3% con tutte le altre armi.", nil, 0x86e39fc3, nil, "um" },
  [415459] = { "Ottieni l'abilità Potenza Magica:\n\n$I1\nAumenta del $N1% il bonus ai danni dei colpi critici di tutti gli incantesimi.", nil, 0xa9c610a1, nil, "um" },
  [415460] = { "Ottieni l'abilità Surriscaldamento:\n\n$I1\nAumenta del $N1% la probabilità di critico magico di tutti i tuoi incantesimi, ma i tuoi critici magici non periodici hanno ora un costo aggiuntivo in mana pari al $N2% del tuo mana base.", nil, 0x912f7738, nil, "um" },
  [415467] = { "Ottieni l'abilità Rigenerazione di Massa:\n\n$I1\nCura di $N2 salute in $D1 tutti i membri del gruppo del giocatore bersaglio che si trovano entro $N1 m da lui e applica a ciascun bersaglio Temporal Beacon per $D2.\n\nTemporal Beacon\n$I2\nRegistra la posizione spazio-temporale del soggetto. Il $N5% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli su cui l'incantatore ha attivo Temporal Beacon. Queste cure sono ridotte del $N6% sull'incantatore stesso, e anche del $N7% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", nil, 0x86eeedaf, nil, "um" },
  [415481] = { "Ottieni l'abilità Dolore e Sofferenza:\n\n$I1\nDetonazione Mentale, Aculeo Mentale e Flagello Mentale riportano alla durata massima una delle tue abilità Parola d'Ombra: Dolore, Void Plague o Tocco Vampirico sul bersaglio. Viene sempre rinnovata l'abilità con la durata rimanente più breve.", nil, 0x7cb5a1d2, nil, "um" },
  [415598] = { "Ottieni l'abilità Gladiator Stance:\n\n$I1\nUna postura aggressiva che, mentre indossi uno scudo, aumenta i danni del $N1% e la probabilità di blocco del $N2%, ma riduce l'Armatura del $N3% e la minaccia generata del $N4%. Inoltre, ottieni il $N5% di rabbia in più quando il tuo attacco automatico danneggia un nemico che non ti ha come bersaglio.\n\nMentre indossi uno scudo in Gladiator Stance, puoi usare tutte le abilità riservate alle altre posture.", nil, 0x319f5c03, nil, "um" },
  [415599] = { "Ottieni l'abilità Single-Minded Fury:\n\n$I1\nMentre combatti con due armi, la tua velocità di movimento aumenta del $N1% e ottieni il $N2% di velocità d'attacco ogni volta che il tuo attacco automatico in mischia colpisce lo stesso bersaglio dell'attacco automatico precedente, effetto che si accumula fino a $N3 volte. Dura $D1 o finché il tuo attacco automatico non colpisce un bersaglio diverso.", nil, 0xc40147a1, nil, "um" },
  [415604] = { "Ottieni l'abilità Everlasting Affliction:\n\n$I1\nOgni volta che il tuo incantesimo Risucchio di Vita, Risucchio d'Anima o Dardo d'Ombra infligge danni, la tua Corruzione sul bersaglio viene riportata alla durata massima.", nil, 0x00f13609, nil, "um" },
  [415605] = { "Ottieni l'abilità Tattiche Demoniache:\n\n$I1\nAumenta del $N1% la probabilità di colpo critico di tutti gli attacchi tuoi e del tuo demone evocato mentre il demone è attivo.", nil, 0xe829f2ef, nil, "um" },
  [415703] = { "Ottieni l'abilità Scudo Sacro:\n\n$I1\nOgni volta che il bersaglio subisce danni ottiene uno Scudo Sacro, che assorbe $N1 danni e aumenta del $N2% la probabilità del Paladino di infliggere un colpo critico con Lampo di Luce per un massimo di $D1. Inoltre, fa sì che il tuo Lampo di Luce curi i bersagli con Scudo Sacro di un ulteriore $N4% in $D2. Non possono ottenere questo effetto più di una volta ogni $D3. Dura $D4. Questo incantesimo non può essere attivo su più di un bersaglio alla volta.", nil, 0xf4acd0fe, nil, "um" },
  [415706] = { "Ottieni l'abilità The Art of War:\n\n$I1\nAumenta del $N1% tutti i danni da sacro che infliggi, e i tuoi colpi critici in mischia e magici riducono di $D1 il tempo di recupero rimanente del tuo incantesimo Esorcismo.", nil, 0xd05623ee, nil, "um" },
  [415709] = { "Ottieni l'abilità Legge del Più Forte:\n\n$I1\nRiduce del $N1% la probabilità di subire colpi critici dagli attacchi in mischia e riduce del $N2% tutti i danni subiti. Danni subiti ridotti di un ulteriore $N3% mentre sei in Forma d'Orso o Dire Bear Form.", nil, 0x55e5ed41, nil, "um" },
  [415712] = { "Ottieni l'abilità ⟦Power Surge=Picco Energetico⟧:\n\n$I1\nOgni volta che Folgore del Fuoco infligge danni, ha il $N1% di probabilità di azzerare il tempo di recupero di Getto di Lava e Catena di Fulmini e di rendere istantaneo il tuo prossimo Getto di Lava o Catena di Fulmini entro $D1. Ogni volta che Marea Gelida cura, ha il $N3% di probabilità di rendere istantanea la tua prossima Catena di Guarigione entro $D2. Inoltre, ogni $D3 ottieni mana pari al $N6% del tuo Intelletto.", nil, 0xc25cf07c, nil, "um" },
  [415713] = { "Ottieni l'abilità Mental Dexterity:\n\n$I1\nAumenta la tua potenza d'attacco di un valore pari al $N1% del tuo Intelletto.", nil, 0x95cf3c2c, nil, "um" },
  [415714] = { "Ottieni l'abilità Pioggia Curativa:\n\n$I1\nSeleziona l'area di $N1 m intorno al giocatore bersaglio e cura tutti i membri del suo gruppo presenti in quell'area di $N2 ogni secondo.", nil, 0x10219417, nil, "um" },
  [415717] = { "Ottieni l'abilità Riflessi Felini:\n\n$I1\nAumenta la tua probabilità di schivata del $N1% e quella del tuo famiglio del $N2%. Inoltre, riduce del $N3% il tempo di recupero della tua abilità Assalto Fiancheggiato.", nil, 0x80e98739, nil, "um" },
  [415718] = { "Ottieni l'abilità Aspetto della Vipera:\n\n$I1\nIl Cacciatore assume l'aspetto della vipera: i tuoi attacchi automatici a distanza e in mischia rigenerano mana, ma i danni totali che infliggi sono ridotti del $N1%. Inoltre, ottieni il $N2% del mana massimo ogni $D1. Il mana ottenuto dipende dalla velocità dell'arma. Può essere attivo un solo Aspetto alla volta.", nil, 0x5189d140, nil, "um" },
  [415719] = { "Ottieni l'abilità Pronto al Tiro:\n\n$I1\nOgni volta che piazzi una trappola, la tua prossima abilità di tiro (tranne Tiro Disorientante) entro $D1 non costa mana e non attiva il tempo di recupero.", nil, 0xea616c73, nil, "um" },
  [415723] = { "Ottieni l'abilità Melee Specialist:\n\n$I1\nAssalto del Raptor è ora istantaneo, e Morso della Mangusta e Assalto del Raptor hanno il $N1% di probabilità a ogni attacco di azzerare i tempi di recupero di Morso della Mangusta e Assalto del Raptor.", nil, 0xfbec55e5, nil, "um" },
  [415725] = { "Ottieni l'abilità Waylay:\n\n$I1\nI tuoi colpi di Imboscata e Pugnalata alle Spalle sbilanciano il bersaglio, aumentando del $N1% l'intervallo tra i suoi attacchi in mischia e riducendone la velocità di movimento del $N2% per $D1.", nil, 0x877c5ec1, nil, "um" },
  [415729] = { "Ottieni l'abilità Illuminazione:\n\n$I1\nInfliggi il $N1% di danni in più finché hai più del $N2% di mana. Quando sei sotto il $N3% di mana, il $N4% della tua rigenerazione del mana continua durante il lancio.", nil, 0xebf46f81, nil, "um" },
  [415734] = { "Ottieni l'abilità Dardo di Geloincanto:\n\n$I1\nScaglia un dardo di geloincanto contro il nemico, infliggendo $N1 danni da geloincanto e rallentandone la velocità di movimento del $N2% per $D1. Per questo incantesimo vale la più bassa tra le resistenze al gelo e all'arcano del bersaglio, e conta sia come danni da gelo sia come danni da arcano.", nil, 0x0e2e915b, nil, "um" },
  [415737] = { "Ottieni l'abilità Provvidenza:\n\n$I1\nLe cure con Cura Rapida riducono del $N1% il tempo di lancio della tua prossima Cura Inferiore, Cura, Cura Maggiore o Preghiera di Cura per $D1, effetto che si accumula fino a $N3 volte.", nil, 0x57fd02db, nil, "um" },
  [415738] = { "Ottieni l'abilità Risonanza Mentale:\n\n$I1\nProvoca un'esplosione di magia d'ombra che danneggia il nemico bersaglio e gli altri nemici vicini, infliggendo $N1 danni da ombra ogni $D1 per $D2 a tutti i nemici entro $N4 m dal bersaglio.", nil, 0x5987ed1e, nil, "um" },
  [415739] = { "Cura Inferiore, Cura, ⟦Greater Heal=Cura Maggiore⟧ e ⟦Flash Heal=Cura Rapida⟧ riducono di $D1 la durata rimanente di ⟦Weakened Soul=Anima Indebolita⟧ sui bersagli che curano. Inoltre, i bersagli della tua ⟦Power Word: Shield=Parola del Potere: Scudo⟧ ottengono rabbia dai danni subiti anche se i danni vengono assorbiti, e ⟦Righteous Fury=Giusta Furia⟧ si attiva con i danni assorbiti dalla tua ⟦Power Word: Shield=Parola del Potere: Scudo⟧ come se fossero una cura.", nil, 0x805cfa98, nil, "um" },
  [415740] = { "Ottieni l'abilità Forza d'Animo:\n\n$I1\nCura Inferiore, Cura, Cura Maggiore e Cura Rapida riducono di $D1 la durata rimanente di Anima Indebolita sui bersagli che curano. Inoltre, i bersagli della tua Parola del Potere: Scudo ottengono rabbia dai danni subiti anche se i danni vengono assorbiti, e Giusta Furia si attiva con i danni assorbiti dalla tua Parola del Potere: Scudo come se fossero una cura.", nil, 0x05224e7d, nil, "um" },
  [415743] = { "Ottieni l'abilità Impeto di Sangue:\n\n$I1\nAssalto Eroico, Sete di Sangue e Turbine hanno una probabilità del $N1% di rendere istantanea la tua prossima Contusione entro $D1, di farla colpire con entrambe le armi da mischia e di renderla senza costo in rabbia.", nil, 0x980b9a0d, nil, "um" },
  [415744] = { "Ottieni l'abilità Precision Timing:\n\n$I1\nContusione ora è istantanea, ma ha un tempo di recupero di $D1.", nil, 0xad79a82b, nil, "um" },
  [415745] = { "Ottieni l'abilità Rabbia Concentrata:\n\n$I1\nRiduce di $N1 il costo in rabbia delle tue abilità offensive.", nil, 0xae0be94f, nil, "um" },
  [415749] = { "Ottieni l'abilità Conoscenza Demoniaca:\n\n$I1\nAumenta i danni magici tuoi e del tuo famiglio demoniaco fino al $N1% del tuo livello mentre hai un famiglio demoniaco evocato attivo.", nil, 0x0fcfc7c4, nil, "um" },
  [415750] = { "Ottieni l'abilità Incenerimento:\n\n$I1\nInfligge $N1 danni da fuoco al bersaglio e un ulteriore $N2% di danni se il bersaglio è afflitto da Immolazione.", nil, 0xdda50ab3, nil, "um" },
  [415751] = { "Ottieni l'abilità Dance of the Wicked:\n\n$I1\nOgni volta che infliggi un colpo critico a un nemico, tu e il tuo famiglio demoniaco ottenete una probabilità di schivata pari al $N1% della tua probabilità di critico magico, e recuperate entrambi il $N2% del mana massimo.", nil, 0x59e67555, nil, "um" },
  [415755] = { "Ottieni l'abilità Protezione della Luce:\n\n$I1\nDopo aver bloccato un attacco in mischia, ottieni il $N1% del tuo mana massimo ogni $D1 per $D2. Questo effetto viene annullato se lanci Lampo di Luce, Luce Sacra o Folgore Sacra.", nil, 0xaebd2851, nil, "um" },
  [415759] = { "Ottieni l'abilità Craniata:\n\n$I1\nCarica un bersaglio entro $N1 m e lo colpisce al cranio, interrompendone il lancio d'incantesimi e impedendo di lanciare incantesimi di quella scuola per $D1. Condivide il tempo di recupero con Carica Ferina.", nil, 0x565688f4, nil, "um" },
  [415760] = { "Ottieni l'abilità Lacerazione:\n\n$I1\nLacera il bersaglio nemico, facendolo sanguinare e infliggendo $N1 danni in $D1, più il $N3% dei danni dell'arma per ogni applicazione di Lacerazione già presente sul bersaglio. Genera un'elevata quantità di minaccia. L'effetto si cumula fino a $N4 volte sullo stesso bersaglio.", nil, 0x9b6d27cf, nil, "um" },
  [415761] = { "Ottieni l'abilità Living Seed:\n\n$I1\nQuando curi in modo critico il bersaglio con un incantesimo di cura non periodico, pianti su di esso un Living Seed pari al $N1% della quantità curata. Il Living Seed sboccia la volta successiva che il bersaglio subisce danni o riceve una cura non periodica. Dura $D1.", nil, 0x5a1b470a, nil, "um" },
  [415762] = { "Ottieni l'abilità Elune's Fires:\n\n$I1\nAlcuni dei tuoi incantesimi e delle tue abilità prolungano la durata dei tuoi effetti di danno e di cura periodici sul bersaglio:\n\nFuoco Stellare prolunga Fuoco Lunare di $D1.\nIra Silvana prolunga Fuoco Solare di $D2.\nRicrescita prolunga Rinvigorimento di $D3.\nArtigliata prolunga Squarcio di $D4.\n\nOgni effetto può essere prolungato al massimo fino alla sua durata iniziale.", nil, 0xfc96a093, nil, "um" },
  [415768] = { "Ottieni l'abilità Vampata:\n\n$I1\nFolgore del Fuoco ora colpisce fino a $N1 bersagli, la sua durata aumenta di $D1 e infligge il $N3% di danni in più. Inoltre, mentre l'arma equipaggiata nella mano primaria è infusa con Arma della Lingua di Fuoco, i tuoi danni magici aumentano di un valore pari al $N4% del tuo Intelletto.", nil, 0x16328d70, nil, "um" },
  [415813] = { "La tua abilità ⟦Ghost Wolf=Lupo Spettrale⟧ ora può essere usata al chiuso e, mentre è attiva, riduce del $N1% tutti i danni che subisci.", nil, 0x25e9c32d, nil, "um" },
  [415816] = { "Ottieni l'abilità Wyvern Strike:\n\n$I1\nSostituisce la tua abilità Morso della Viverna con Wyvern Strike, un assalto feroce che infligge il $N1% dei danni dell'arma e fa sanguinare il bersaglio, infliggendo danni nel tempo.\n\nWyvern Strike richiede il talento Morso della Viverna e sostituisce le abilità Morso della Viverna del libro degli incantesimi Sopravvivenza.", nil, 0x49d2169d, nil, "um" },
  [415817] = { "Ottieni l'abilità Uccisione Rapida:\n\n$I1\nRiduce il tempo di recupero della tua abilità Rapidità di Tiro di $D1. Inoltre, quando uccidi un nemico non banale o questi muore mentre è afflitto dal tuo Morso del Serpente, ottieni Uccisione Rapida, che aumenta del $N3% i danni della tua prossima abilità di tiro entro $D2.", nil, 0xe18ce1c0, nil, "um" },
  [415818] = { "Ottieni l'abilità Sniper Training:\n\n$I1\nQuando non ti sei mosso nell'ultimo $D1, hai il $N2% di probabilità di ottenere Sniper's Aim, cumulabile fino a $N3 volte. Sniper's Aim aumenta del $N4% la probabilità di critico delle tue abilità di tiro.", nil, 0x8f9ebf59, nil, "um" },
  [415822] = { "Ottieni l'abilità Raptor Fury:\n\n$I1\nAssalto del Raptor aumenta del $N1% i danni inflitti da Assalto del Raptor e Morso della Mangusta per $D1, effetto cumulabile fino a $N3 volte. Le applicazioni successive non prolungano la durata di questo effetto.", nil, 0xf318fadb, nil, "um" },
  [415918] = { "Incidi sul tuo mantello la runa Tempesta Cremisi:\n\n$I1\nMossa risolutiva che squarcia tutti i nemici entro $N1 m, facendoli sanguinare nel tempo. Dura di più e infligge più danni per ogni punto combo.\n\n$N2 punto: $N3 danni in $D1.\n $N5 punti: $N6 danni in $D2.\n $N8 punti: $N9 danni in $D3.\n $N11 punti: $N12 danni in $D4.\n $N14 punti: $N15 danni in $D5.\n\nTempesta Cremisi beneficia di tutti i talenti e gli effetti che si attivano da Perforazione o la modificano.", nil, 0xe3ea95b8, nil, "um" },
  [415922] = { "Incidi sul tuo mantello la runa Schioppo:\n\n$I1\nSpara una raffica di moschetto contro un massimo di $N1 nemici in un cono davanti a te, infliggendo $N2 danni fisici.", nil, 0xce5a37fe, nil, "um" },
  [415926] = { "Incidi sui tuoi stivali la runa Waylay:\n\n$I1\nI tuoi colpi di Imboscata e Pugnalata alle Spalle sbilanciano il bersaglio, aumentando del $N1% l'intervallo tra i suoi attacchi in mischia e riducendone la velocità di movimento del $N2% per $D1.", nil, 0x8f27a210, nil, "um" },
  [415934] = { "Incidi sui tuoi stivali la runa Potenza Magica:\n\n$I1\nAumenta del $N1% il bonus ai danni dei colpi critici di tutti gli incantesimi.", nil, 0xf49948f2, nil, "um" },
  [415936] = { "Incidi sui tuoi guanti la runa ⟦Living Bomb=Bomba Vivente⟧:\n\n$I1\nIl bersaglio diventa una ⟦Living Bomb=Bomba Vivente⟧ e subisce $N1 danni da fuoco in $D1. Dopo $D2 o quando l'incantesimo viene dissolto, il bersaglio esplode infliggendo $N4 danni da fuoco a tutti i nemici entro $N5 m.\n\n⟦Living Bomb=Bomba Vivente⟧ beneficia di tutti i talenti e gli effetti che si attivano da Bruciatura o la modificano.", nil, 0x7a583662, nil, "um" },
  [415939] = { "Incidi sui tuoi gambali la runa Rigenerazione di Massa:\n\n$I1\nCura di $N2 salute in $D1 tutti i membri del gruppo del giocatore bersaglio che si trovano entro $N1 m da lui e applica Temporal Beacon a ciascun bersaglio per $D2.\n\nTemporal Beacon\n$I2\nRegistra la posizione spazio-temporale del soggetto. Il $N5% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N6% su sé stessi, e ridotta anche del $N7% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", nil, 0x7d1b407b, nil, "um" },
  [415942] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Illuminazione:\n\n$I1\nInfliggi il $N1% di danni in più finché hai più del $N2% di mana. Quando sei sotto il $N3% di mana, il $N4% della tua rigenerazione del mana continua durante il lancio.", nil, 0xe36c7b47, nil, "um" },
  [415948] = { "Incidi sulla tua cintura la runa Dardo di Geloincanto:\n\n$I1\nScaglia un dardo di geloincanto contro il nemico, infliggendo $N1 danni da geloincanto e rallentandone la velocità di movimento del $N2% per $D1. Per questo incantesimo vale la più bassa tra le resistenze al gelo e all'arcano del bersaglio, e conta sia come danni da gelo sia come danni da arcano.", nil, 0x0e2ee4df, nil, "um" },
  [415991] = { "Incidi sul tuo elmo la runa Dolore e Sofferenza:\n\n$I1\nDetonazione Mentale, Aculeo Mentale e Flagello Mentale riportano alla durata massima una delle tue abilità Parola d'Ombra: Dolore, Void Plague o Tocco Vampirico sul bersaglio. Viene sempre rinnovata l'abilità con la durata rimanente più breve.", nil, 0x1765a845, nil, "um" },
  [415995] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Provvidenza:\n\n$I1\nLe cure con Cura Rapida riducono del $N1% il tempo di lancio della tua prossima Cura Inferiore, Cura, Cura Maggiore o Preghiera di Cura per $D1, effetto che si accumula fino a $N3 volte.", nil, 0x15382fc4, nil, "um" },
  [415996] = { "Incidi sui tuoi guanti la runa Risonanza Mentale:\n\n$I1\nProvoca un'esplosione di magia d'ombra che danneggia il nemico bersaglio e gli altri nemici vicini, infliggendo $N1 danni da ombra ogni $D1 per $D2 a tutti i nemici entro $N4 m dal bersaglio.", nil, 0xc0148127, nil, "um" },
  [415997] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Forza d'Animo:\n\n$I1\nCura Inferiore, Cura, Cura Maggiore e Cura Rapida riducono di $D1 la durata rimanente di Anima Indebolita sui bersagli che curano. Inoltre, i bersagli della tua Parola del Potere: Scudo ottengono rabbia dai danni subiti anche se i danni vengono assorbiti, e Giusta Furia si attiva con i danni assorbiti dalla tua Parola del Potere: Scudo come se fossero una cura.", nil, 0x28fd638c, nil, "um" },
})
